document.addEventListener('DOMContentLoaded',()=>{
  const api=window.RekordAI,$=id=>document.getElementById(id),selected=new Map(),usbSelected=new Set();
  const cancelSteps=document.createElement('button');cancelSteps.type='button';cancelSteps.className='btn btn-secondary';cancelSteps.textContent='Detener consulta de varios pasos';$('chat-form').after(cancelSteps);cancelSteps.onclick=async()=>{try{const state=await api.post('/api/chat/cancel-steps',{});api.notice(state.note);}catch(e){api.notice(e.message,'error');}};
  let offset=0,filters={},audit=null,usbOffset=0,preview=null,job=null,busy=false,revision=null;
  const node=(tag,value)=>{const n=document.createElement(tag);n.textContent=String(value);return n;};
  const tool=(name,args={})=>api.post('/api/toolbox/execute',{name,arguments:args});
  const action=(id,fn)=>{$(id).onclick=async()=>{const button=$(id);button.disabled=true;try{await fn();}catch(e){api.notice(e.message,'error');}finally{button.disabled=false;}};};
  function show(id,data){
    const out=$(id);out.replaceChildren();const line=value=>out.append(node('p',value));
    for(const key of ['resumen','respaldo','reason','note','analysis_note','warning'])if(data[key])line(data[key]);
    if(data.mode&&data.decks){line(({simulation:'SIMULACIÓN · paquetes sintéticos',receiving:'Recepción UDP activa',stopped:'Receptor detenido',failed:'Recepción interrumpida'})[data.mode]||data.mode);for(const d of data.decks)line(`${d.name} · deck ${d.player} · ID externo ${d.external_track_id} · ${d.bpm??'?'} BPM · ${d.position_seconds==null?'posición no informada':d.position_seconds+' s'} · ${d.fresh?(d.playing?'reproduciendo':'pausado'):'estado vencido'} · On-Air ${d.on_air_reported?'informado':'no informado'}`);if(data.ambiguous)line('Más de un deck informa On-Air; no se elige un master audible.');if(data.error)line(data.error);return;}
    if(data.state)line(data.state==='applied'?'Operación aplicada.':'Estado: '+data.state);
    if(data.backup_directory)line('Respaldo: '+data.backup_directory);
    if(data.title)line(data.title);
    if(data.hot_cues!=null)line(`${data.hot_cues} hot cues · ${data.memory_cues} memory cues · ${data.loops} loops · beatgrid ${data.beatgrid_present?'presente (precisión sin certificar)':'no disponible'}`);
    for(const c of data.cues||[])line(`${c.hot_cue?'Hot Cue '+String.fromCharCode(64+c.hot_cue):'Memory Cue'} · ${c.start} s${c.loop?' → '+c.end+' s (loop)':''} · ${c.name||''}`);
    for(const p of data.phrases||[])line(`Frase ${p.label} · beat ${p.beat} · ${p.start_seconds.toFixed(2)} s`);
    if(data.available===true)line(`Iniciá la mezcla a los ${data.start_outgoing_seconds.toFixed(2)} s de la saliente, desde ${data.start_incoming_seconds.toFixed(2)} s de la entrante. ${data.bars} compases ≈ ${data.mix_duration_seconds} s, asumiendo 4/4.`);
    for(const h of data.harmonic_options||[])line(`${h.manual_action} → ${h.resulting_key}`);
    if(data.total!=null)line(`${data.total} pistas · página desde ${data.offset||0}`);
    if(data.checked!=null)line(`${data.checked} archivos comprobados de ${data.total_tracks}. ${data.missing_in_page} ausentes o inaccesibles en esta página.`);
    for(const t of data.tracks||[])line(`${t.title} · ID ${t.track_id||t.id} · ${t.file_available===false?'archivo no accesible · ':''}${t.hot_cues??0} hot cues · ${t.memory_cues??0} memory cues · ${t.loops??0} loops · ${t.phrases?.length??0} frases${t.missing_bpm?' · sin BPM':''}${t.missing_key?' · sin tonalidad':''}`);
    for(const t of data.files||[])if(t.state!=='available')line(`${t.artist} — ${t.title} · ID ${t.id}: archivo ausente o inaccesible`);
    for(const t of data.recommendations||[])line(`${t.artist} — ${t.title} · ID ${t.id} · ${(t.match_reasons||[]).join(' · ')}${t.match_details?.key_shift_semitones?' · aplicar Key Shift '+t.match_details.key_shift_semitones+' → '+t.match_details.resulting_key:''}`);
    if(data.integrated_lufs!==undefined)line(`Sonoridad integrada: ${data.integrated_lufs??'silencio / no medible'} LUFS · subgraves ${(100*data.sub_bass_ratio).toFixed(1)}% · transientes ${data.transients_per_second}/s · energía estimada ${data.value}/10. ${data.limitations||''}`);
  }
  async function sources(){const r=await api.apiFetch('/api/status'),s=await r.json();if(!r.ok)throw Error(s.error);$('lab-source').textContent=`${s.source_kind==='native_snapshot'?'Colección viva':'XML exportado'} · ${s.tracks_count} pistas${s.snapshot_at?' · '+s.snapshot_at:''}`;if(revision&&revision!==s.snapshot_revision){selected.clear();$('lab-tracks').replaceChildren();}revision=s.snapshot_revision;const p=await api.apiFetch('/api/playlists'),data=await p.json();$('lab-playlist').replaceChildren(new Option('Toda la colección',''));for(const row of data.playlists||[])$('lab-playlist').add(new Option(row.path,row.path));if(s.source_kind==='native_snapshot'){const tags=await tool('collection.tags');$('lab-tags').replaceChildren();for(const t of tags.tags)$('lab-tags').add(new Option(`${t.category} / ${t.name}`,t.id));}}
  action('lab-connect',async()=>{await api.post('/api/library/native',{});await api.refreshStatus();await sources();api.notice('Colección viva conectada en modo lectura.');});
  async function search(more){if(!more){offset=0;selected.clear();$('lab-tracks').replaceChildren();filters={query:$('lab-query').value,min_rating:$('lab-rating').value===''?null:Number($('lab-rating').value),unplayed:$('lab-unplayed').checked,added_after:$('lab-date').value,tags:[...$('lab-tags').selectedOptions].map(o=>o.value),sort_by_date:true};}const data=await tool('collection.query',{...filters,offset,limit:50});if(more&&revision!==data.source_revision)throw Error('La colección cambió; repetí la búsqueda.');revision=data.source_revision;$('lab-count').textContent=`${data.total} resultados en toda la colección · ${selected.size} seleccionadas`;for(const track of data.tracks){const label=node('label',''),box=document.createElement('input');box.type='checkbox';box.onchange=()=>{if(box.checked)selected.set(track.id,track);else selected.delete(track.id);$('lab-count').textContent=`${data.total} resultados · ${selected.size} seleccionadas`;};label.append(box,node('span',`${track.artist} — ${track.title} · ID ${track.id} · ${track.bpm??'?'} BPM · ${track.key??'?'} · ${track.rating??'?'} ★`));label.style.display='block';$('lab-tracks').append(label);}offset+=data.tracks.length;$('lab-more').hidden=offset>=data.total;}
  $('lab-filter').onsubmit=async e=>{e.preventDefault();try{await search(false);}catch(error){api.notice(error.message,'error');}};
  action('lab-more',()=>search(true));
  action('lab-plan',async()=>{window.dispatchEvent(new CustomEvent('select-library-tracks',{detail:[...selected.values()]}));$('plan-source').value='selected';document.querySelector('[data-tab="tab-planner"]').click();});
  action('lab-structure',async()=>show('lab-structure-result',await tool('track.structure',{track_id:$('lab-from').value.trim()})));
  action('lab-transition',async()=>show('lab-structure-result',await tool('transition.phrase',{from_id:$('lab-from').value.trim(),to_id:$('lab-to').value.trim(),bars:Number($('lab-bars').value)})));
  action('lab-recommend',async()=>show('lab-structure-result',await tool('recommend.key_shift',{track_id:$('lab-from').value.trim(),max_key_shift:Number($('lab-shift').value)})));
  $('lab-shift').onchange=()=>api.post('/api/settings',{recommendation:{max_key_shift:Number($('lab-shift').value)}}).catch(e=>api.notice(e.message,'error'));
  async function runAudit(name,more=false){if(!more)audit={name,offset:0,playlist:$('lab-playlist').value||null,revision:null};const data=await tool(audit.name,{offset:audit.offset,limit:100,...(audit.name==='set.preshow'?{playlist:audit.playlist}:{})});if(audit.revision&&audit.revision!==data.source_revision)throw Error('La colección cambió; reiniciá la auditoría.');audit.revision=data.source_revision;show('lab-structure-result',data);audit.offset=data.next_offset;$('lab-next-audit').hidden=audit.offset==null;}
  action('lab-preshow',()=>runAudit('set.preshow'));action('lab-missing',()=>runAudit('collection.missing_files'));action('lab-next-audit',()=>runAudit(null,true));
  function showJob(data){job=data;$('lab-audio-state').textContent=`${data.state} · ${data.processed||0}/${data.total||0} · analizadas ${data.analyzed||0} · errores ${data.failed||0}${data.error?' · '+data.error:''}`;}
  action('lab-audio-selected',async()=>showJob(await api.post('/api/analysis/start',{track_ids:[...selected.keys()]})));
  action('lab-audio-playlist',async()=>{if(!$('lab-playlist').value&&!window.confirm('¿Analizar toda la colección? Puede demorar. Podés cancelar y conservar lo calculado.'))return;showJob(await api.post('/api/analysis/start',{playlist:$('lab-playlist').value||null}));});
  action('lab-audio-cancel',async()=>{if(job?.job_id)showJob(await api.post('/api/analysis/cancel',{job_id:job.job_id}));});
  const measured=node('button','Ver medición de la pista saliente');measured.className='btn btn-secondary';$('lab-audio-state').before(measured);measured.onclick=async()=>{try{show('lab-structure-result',await api.post('/api/analysis/track',{track_id:$('lab-from').value.trim()}));$('lab-structure-result').scrollIntoView({block:'center'});}catch(e){api.notice(e.message,'error');}};
  action('lab-usb-detect',async()=>{const d=await api.post('/api/device/discover',{});$('lab-usb').replaceChildren();for(const x of d.devices)$('lab-usb').add(new Option(x.root,x.device_id));if(!d.devices.length)api.notice('No se encontró un USB con export.pdb.');});
  async function usbAudit(more){if(!more){usbOffset=0;usbSelected.clear();$('lab-usb-result').replaceChildren();}const d=await api.post('/api/device/inspect',{device_id:$('lab-usb').value,offset:usbOffset});$('lab-usb-result').append(node('p',`${d.total_tracks} pistas · ${d.orphan_count} referencias huérfanas · Device Library Plus: ${d.device_library_plus_present?'sí':'no'}`));for(const t of d.tracks){const label=node('label',''),check=document.createElement('input');check.type='checkbox';check.onchange=()=>check.checked?usbSelected.add(t.id):usbSelected.delete(t.id);label.append(check,node('span',`${t.title} · ID ${t.id} · audio ${t.file_available?'OK':'ausente'} · análisis ${t.analysis_available?'OK':'ausente'}`));label.style.display='block';$('lab-usb-result').append(label);}usbOffset=d.next_offset;$('lab-usb-more').hidden=usbOffset==null;}
  action('lab-usb-audit',()=>usbAudit(false));action('lab-usb-more',()=>usbAudit(true));
  $('lab-usb').onchange=()=>{preview=null;usbSelected.clear();$('lab-usb-apply').hidden=true;};
  async function prepareUsb(existing){preview=null;$('lab-usb-apply').hidden=true;preview=await api.post('/api/device/export/prepare',{device_id:$('lab-usb').value,name:$('lab-usb-name').value,...(existing?{device_track_ids:[...usbSelected]}:{track_ids:[...selected.keys()]})});show('lab-usb-preview',{resumen:preview.summary,respaldo:preview.backup_directory});$('lab-usb-apply').hidden=false;}
  action('lab-usb-existing',()=>prepareUsb(true));action('lab-usb-new',()=>prepareUsb(false));
  action('lab-usb-backups',async()=>{const data=await api.post('/api/device/backups',{});$('lab-usb-backup').replaceChildren();for(const b of data.backups)$('lab-usb-backup').add(new Option(`${b.device_root} · ${b.name}`,b.operation_id));});
  action('lab-usb-restore',async()=>{preview=null;$('lab-usb-apply').hidden=true;preview=await api.post('/api/device/restore/prepare',{operation_id:$('lab-usb-backup').value});show('lab-usb-preview',{resumen:preview.summary,respaldo:preview.backup_directory});$('lab-usb-apply').hidden=false;});
  action('lab-usb-apply',async()=>{if(!preview)throw Error('Prepará una propuesta vigente.');if(!window.__TAURI__)throw Error('Confirmá desde la aplicación Windows.');const result=await window.__TAURI__.core.invoke('approve_native_operation',{token:preview.token});preview=null;$('lab-usb-apply').hidden=true;show('lab-usb-preview',result);});
  action('lab-link-sim',async()=>show('lab-link-result',await api.post('/api/link/simulate',{})));
  action('lab-link-start',async()=>show('lab-link-result',await api.post('/api/link/start',{bind_address:$('lab-link-ip').value})));
  action('lab-link-stop',async()=>show('lab-link-result',await api.post('/api/link/stop',{})));
  document.querySelector('[data-tab="tab-lab"]').addEventListener('click',()=>sources().catch(e=>api.notice(e.message,'error')));
  setInterval(async()=>{if(busy||!$('tab-lab').classList.contains('active'))return;busy=true;try{showJob(await api.post('/api/analysis/status',{}));show('lab-link-result',await api.post('/api/link/status',{}));}catch(e){$('lab-audio-state').textContent=e.message;}finally{busy=false;}},2500);
});
